        }

        .login-marca__circulo {
            position: absolute;
            border-radius: 50%;
            background-color: var(--azul-header-oscuro);
        }
        /* Círculo tipo "anillo" arriba a la izquierda: aro oscuro con el centro
           del mismo color que el fondo, para que se vea hueco */
        .login-marca__circulo--anillo {
            width: 210px;
            height: 210px;
            top: -70px;
            left: -70px;
        }
        .login-marca__circulo--anillo::after {
